import React, { useState, useEffect } from 'react';
import { 
  Container, 
  Grid, 
  Typography, 
  Box, 
  Tabs, 
  Tab, 
  CircularProgress,
  Button,
  Alert
} from '@mui/material';
import axios from 'axios';
import ContentCard from './ContentCard';
import MovieCarousel from './MovieCarousel';

const Home = () => {
  const [activeTab, setActiveTab] = useState(0);
  const [trending, setTrending] = useState([]);
  const [popularMovies, setPopularMovies] = useState([]);
  const [popularTVShows, setPopularTVShows] = useState([]);
  const [topRatedMovies, setTopRatedMovies] = useState([]);
  const [topRatedTVShows, setTopRatedTVShows] = useState([]);
  const [upcomingMovies, setUpcomingMovies] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [page, setPage] = useState(1);

  useEffect(() => {
    const fetchData = async () => {
      try {
        setLoading(true);
        const token = localStorage.getItem('token');
        const config = {
          headers: {
            'x-auth-token': token
          }
        };

        const [
          trendingRes,
          popularMoviesRes,
          popularTVShowsRes,
          topRatedMoviesRes,
          topRatedTVShowsRes,
          upcomingMoviesRes
        ] = await Promise.all([
          axios.get('/api/movies/trending', config),
          axios.get('/api/movies/popular/movie', config),
          axios.get('/api/movies/popular/tv', config),
          axios.get('/api/movies/top/movie', config),
          axios.get('/api/movies/top/tv', config),
          axios.get('/api/movies/upcoming', config)
        ]);

        setTrending(trendingRes.data);
        setPopularMovies(popularMoviesRes.data.results || []);
        setPopularTVShows(popularTVShowsRes.data.results || []);
        setTopRatedMovies(topRatedMoviesRes.data.results || []);
        setTopRatedTVShows(topRatedTVShowsRes.data.results || []);
        setUpcomingMovies(upcomingMoviesRes.data.results || []);
        setError(null);
      } catch (err) {
        console.error('Error fetching data:', err);
        setError(err.response?.data?.msg || 'Error fetching data. Please try again later.');
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handleTabChange = (event, newValue) => {
    setActiveTab(newValue);
  };

  const loadMore = async () => {
    try {
      setLoading(true);
      const token = localStorage.getItem('token');
      const config = {
        headers: {
          'x-auth-token': token
        }
      };

      const newPage = page + 1;
      const [popularMoviesRes, popularTVShowsRes] = await Promise.all([
        axios.get(`/api/movies/popular/movie?page=${newPage}`, config),
        axios.get(`/api/movies/popular/tv?page=${newPage}`, config)
      ]);

      setPopularMovies([...popularMovies, ...(popularMoviesRes.data.results || [])]);
      setPopularTVShows([...popularTVShows, ...(popularTVShowsRes.data.results || [])]);
      setPage(newPage);
    } catch (err) {
      console.error('Error loading more content:', err);
      setError(err.response?.data?.msg || 'Error loading more content. Please try again later.');
    } finally {
      setLoading(false);
    }
  };

  if (loading && page === 1) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" minHeight="80vh">
        <CircularProgress />
      </Box>
    );
  }

  if (error) {
    return (
      <Container maxWidth="xl">
        <Box sx={{ mt: 4 }}>
          <Alert severity="error">{error}</Alert>
        </Box>
      </Container>
    );
  }

  return (
    <Container maxWidth="xl">
      {/* Movie Carousel */}
      {trending.length > 0 && (
        <Box sx={{ mt: 2 }}>
          <MovieCarousel movies={trending.slice(0, 5)} />
        </Box>
      )}

      <Box sx={{ width: '100%', mt: 4 }}>
        <Tabs
          value={activeTab}
          onChange={handleTabChange}
          variant="scrollable"
          scrollButtons="auto"
          sx={{ mb: 4 }}
        >
          <Tab label="Trending" />
          <Tab label="Popular Movies" />
          <Tab label="Popular TV Shows" />
          <Tab label="Top Rated Movies" />
          <Tab label="Top Rated TV Shows" />
          <Tab label="Upcoming Movies" />
        </Tabs>

        {activeTab === 0 && (
          <>
            <Typography variant="h4" gutterBottom>
              Trending Now
            </Typography>
            <Grid container spacing={3}>
              {trending.map((item) => (
                <Grid item xs={12} sm={6} md={4} lg={3} key={item.id}>
                  <ContentCard content={item} />
                </Grid>
              ))}
            </Grid>
          </>
        )}

        {activeTab === 1 && (
          <>
            <Typography variant="h4" gutterBottom>
              Popular Movies
            </Typography>
            <Grid container spacing={3}>
              {popularMovies.map((movie) => (
                <Grid item xs={12} sm={6} md={4} lg={3} key={movie.id}>
                  <ContentCard content={movie} />
                </Grid>
              ))}
            </Grid>
            <Box display="flex" justifyContent="center" mt={4}>
              <Button
                variant="contained"
                onClick={loadMore}
                disabled={loading}
              >
                {loading ? 'Loading...' : 'Load More'}
              </Button>
            </Box>
          </>
        )}

        {activeTab === 2 && (
          <>
            <Typography variant="h4" gutterBottom>
              Popular TV Shows
            </Typography>
            <Grid container spacing={3}>
              {popularTVShows.map((show) => (
                <Grid item xs={12} sm={6} md={4} lg={3} key={show.id}>
                  <ContentCard content={show} />
                </Grid>
              ))}
            </Grid>
            <Box display="flex" justifyContent="center" mt={4}>
              <Button
                variant="contained"
                onClick={loadMore}
                disabled={loading}
              >
                {loading ? 'Loading...' : 'Load More'}
              </Button>
            </Box>
          </>
        )}

        {activeTab === 3 && (
          <>
            <Typography variant="h4" gutterBottom>
              Top Rated Movies
            </Typography>
            <Grid container spacing={3}>
              {topRatedMovies.map((movie) => (
                <Grid item xs={12} sm={6} md={4} lg={3} key={movie.id}>
                  <ContentCard content={movie} />
                </Grid>
              ))}
            </Grid>
          </>
        )}

        {activeTab === 4 && (
          <>
            <Typography variant="h4" gutterBottom>
              Top Rated TV Shows
            </Typography>
            <Grid container spacing={3}>
              {topRatedTVShows.map((show) => (
                <Grid item xs={12} sm={6} md={4} lg={3} key={show.id}>
                  <ContentCard content={show} />
                </Grid>
              ))}
            </Grid>
          </>
        )}

        {activeTab === 5 && (
          <>
            <Typography variant="h4" gutterBottom>
              Upcoming Movies
            </Typography>
            <Grid container spacing={3}>
              {upcomingMovies.map((movie) => (
                <Grid item xs={12} sm={6} md={4} lg={3} key={movie.id}>
                  <ContentCard content={movie} />
                </Grid>
              ))}
            </Grid>
          </>
        )}
      </Box>
    </Container>
  );
};

export default Home;
